char* duplicateString(char* base, char* middle, int times)
{
    // zeroed dynamic array
    char* str = calloc(times * strlen(base) + (times - 1) * strlen(middle) + 1,
        sizeof(char));
    int i;

    for (i = 1; i <= times - 1; i++)
    {
        strcat(str, base);
        strcat(str, middle);
    }
    strcat(str, base);
    return str;
}
```

