typedef struct item {
    int data;
    struct item* next;
}Item;

/* Auxiliary function: estimation of the size of a number */
int countDigit(int number)
{
    int j = 0;
    while (number)
    {
        ++j;
        number /= 10;
    }
    return j;
}
```
